                    at.1 = bounds;
                } else {
                    at.0 = bounds;
                }
            },
            |_, _, _, _| {},
        )
        .absolute()
        .top_0()
        .left_0()
        .size_full()
    };
    // A list, as Trello draws one: on the recessed surface, one step
    // from the board's base, its corners rounded, with no border, but
    // pressed into the base, and its column's colour along its top.
