                ColumnEntry::Card { ix, .. } if stories[*ix].name == anchor.as_ref() => Some(*top),
                _ => None,
            })
        {
            top += now - was;
        }
        let height = match handle.bounds().size.height {
            height if height > px(0.) => height,
            _ => window.viewport_size().height,
        };
